import re
ids = ["M-154","M-330","M-388","M-389","M-390","M-391","M-392","M-393","M-394","M-397","M-401","M-461","M-466"]
def load(path):
    rows = {}
    with open(path) as f:
        for line in f:
            m = re.match(r'^\| (M-\d+) \|(.*)\|$', line.rstrip('\n'))
            if m: rows[m.group(1)] = m.group(2)
    return rows
old = load('/tmp/old_matrix.md'); new = load('TEST_MATRIX.md')
for rid in ids:
    on = old[rid].lower().count('never')
    nn = new[rid].lower().count('never')
    print(rid, "never count old/new:", on, nn, "OK" if on==nn else "MISMATCH")
EOF
